{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.LOGIC_FINAL_ITEM_MASTER AS select distinct usercode, COMP_NAME as BRAND, usercode AS SKU, ADDLITEMCODE AS DETAILEDSKU, ITEMNAMEWOSHADE AS SKUGROUP, SHADE_NAME AS COLOR, PACKNAME AS SIZE, ITEMNAMEWITHSHADE AS STYLE, purrate::integer as BASE_PRICE, basicrate::integer as COST_PRICE, MRP::integer as MRP, PACKING AS UNIT, ITEM_DESCRIPTION AS SKU_GROUP, GROUP_NAME1 AS CATEGORY, GROUP_NAME2 AS CLOTHGROUP, GROUP_NAME3 AS GENDER, GROUP_NAME4 AS FIT, HSN_CODE as HSN_CODE, GROUP_NAME25 AS HSNGROUP, GROUP_NAME30 AS GSTTYPE, MODIFYDATE AS UPDATEDDATE, CREATEDATE AS CREATEDDATE, GROUP_SHORT_NAME1 AS SKUTYPE, FLAG, GROUP_NAME11 AS DIM1, GROUP_NAME12 AS DIM2, GROUP_NAME13 AS DIM3, GROUP_NAME30 AS GST, RAW_OR_FINISH AS FINISHTYPE, ADDL_ITEM_NAME AS ITEMNAME, DAYS_TO_EXPIRE AS EXPIRY, ITEMDETAILCODE AS ITEMCODE, COMP_SHORT_NAME AS BRANDNAME, RO_LEVEL, MAX_LEVEL, MIN_LEVEL, INACTIVE_FOR_PO, INACTIVE_FOR_PR, INACTIVE_FOR_PU, INACTIVE_FOR_SL, INACTIVE_FOR_SO, INACTIVE_FOR_SR from snitch_db.maplemonk.logic_get_item_master; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.OFFLINE_STORE_DETAILED_MAPPING AS select distinct TRIM(RTRIM(REGEXP_SUBSTR(stock_transfer_branchname, \'^[^-]*-[^-]*-[^-]*\', 1, 1), \'-\')) as store_name, city_name as region, state_name as cluster, stock_transfer_branchcode as store_code, group_name3 as party from snitch_db.maplemonk.logicERPnew_get_party_master ; CREATE OR REPLACE TABLE snitch_db.maplemonk.sto_analysis AS WITH final_sto_data AS ( SELECT ORIGIN, TO_DATE(bill_date, \'DD/MM/YYYY\') AS DATE, TO_TIMESTAMP(bill_time, \'DD/MM/YYYY HH12:MI AM\') as time, to_party, from_party, item_quantity, bill_no, order_no, total_quantity, doc_number, net_amount, vouch_code, so_order_no, account_code, sku, item_group_name_1 AS category, item_mrp FROM snitch_db.maplemonk.logic_final_sto WHERE lower(sku) NOT LIKE \'%cb%\' ), final_data_with_store_details AS ( SELECT fsd.*, gs.store_name, gs.cluster, gs.region FROM final_sto_data fsd LEFT JOIN SNITCH_DB.MAPLEMONK.OFFLINE_STORE_DETAILED_MAPPING gs ON fsd.from_party = gs.store_name ) SELECT * FROM final_data_with_store_details; CREATE OR REPLACE TABLE snitch_db.maplemonk.sti_analysis AS WITH final_sti_data AS ( SELECT ORIGIN, bill_date AS DATE, from_party, to_party, item_quantity, bill_no, total_quantity, net_amount, vouch_code, account_code, sku, item_mrp FROM snitch_db.maplemonk.logic_final_sti WHERE lower(sku) NOT LIKE \'%cb%\' ), final_data_with_store_details AS ( SELECT fsd.*, gs.store_name, gs.cluster, gs.region FROM final_sti_data fsd LEFT JOIN snitch_db.maplemonk.offline_store_detailed_mapping gs ON fsd.to_party = gs.store_name ) SELECT * FROM final_data_with_store_details; CREATE OR REPLACE TABLE snitch_db.maplemonk.purchasev_analysis AS WITH final_purchasev_data AS ( SELECT ORIGIN, bill_date AS DATE, from_party, to_party, item_quantity, bill_no, quantity as total_quantity, net_amount, vouch_code, account_code, ADDLITEMCODE as sku, item_mrp FROM snitch_db.maplemonk.logic_purchase_voucher WHERE lower(sku) NOT LIKE \'%cb%\' ), final_data_with_store_details AS ( SELECT fpd.*, gs.store_name, gs.cluster, gs.region FROM final_purchasev_data fpd LEFT JOIN snitch_db.maplemonk.offline_store_detailed_mapping gs ON fpd.to_party = gs.store_name ) SELECT * FROM final_data_with_store_details; CREATE OR REPLACE TABLE snitch_db.maplemonk.logic_store_inward AS WITH sti_data AS ( SELECT ORIGIN, DATE, from_party, to_party, item_quantity, bill_no, total_quantity, net_amount, vouch_code, account_code, sku, item_mrp, store_name, cluster, region FROM snitch_db.maplemonk.sti_analysis ), purchasev_data AS ( SELECT ORIGIN, DATE, from_party, to_party, item_quantity, bill_no, total_quantity, net_amount, vouch_code, account_code, sku, item_mrp, store_name, cluster, region FROM snitch_db.maplemonk.purchasev_analysis ) SELECT * FROM sti_data UNION ALL SELECT * FROM purchasev_data; CREATE OR REPLACE TABLE snitch_db.maplemonk.outward_accuracy AS WITH match1 AS ( SELECT TRY_TO_DATE(DATE, \'DD/MM/YYYY\') AS raised_date, type, store, uniquecode AS request_no, NULLIF(so_number, \'-\') AS Sale_NUMBER, quantity AS qty_raised, CONCAT(sale_number, store) AS match1 FROM snitch_db.maplemonk.gs_store_outward_tracker_store ), match2 AS ( SELECT bill_no, so_order_no, quantity AS qty_completed, try_to_date(bill_date,\'DD/MM/YYYY\') as bill_date, branch_name, CONCAT(SO_ORDER_NO, BRANCH_NAME) AS match2 FROM snitch_db.maplemonk.logicstream_get_stock_transfer_out WHERE branch_name LIKE \'%CO%\' OR branch_name LIKE \'%FO%\' ), final_combination AS ( SELECT m1.raised_date, m1.type, m1.store, m1.request_no, m1.Sale_NUMBER, m1.qty_raised, m2.bill_no, m2.so_order_no, m2.qty_completed, m2.bill_date, m2.branch_name, m1.qty_raised - m2.qty_completed AS miss_quantity FROM match1 m1 LEFT JOIN match2 m2 ON m1.match1 = m2.match2 ), final_data_with_store_details AS ( SELECT fc.*, sd.store_name, sd.cluster, sd.region FROM final_combination fc LEFT JOIN snitch_db.maplemonk.OFFLINE_STORE_DETAILED_MAPPING sd ON fc.store = sd.store_name ) SELECT * FROM final_data_with_store_details; ;",
                    "transaction": true
                }
            ) }}
